def esta_en(ordenada, x, inicio=0, fin=None):
    if fin is None:
        fin = len(ordenada) - 1
    if inicio > fin:
        return False
    medio = (inicio + fin) // 2
    if ordenada[medio] == x:
        return True
    if ordenada[medio] > x:
        return esta_en(ordenada, x, inicio, medio - 1)
    return esta_en(ordenada, x, medio + 1, fin)

esta_en([2, 5, 8, 12, 20], 12)  # True

